import sys,math,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();Q=np.array([0.,1.,0.,0.],np.float32);MPP=.00022186

def xy(u,v):return np.array([.0135925-(v+.5)*MPP,.1135925-(u+.5)*MPP])
def P(u,v,z):return np.r_[xy(u,v),z,Q]
def xyz(x,y,z):return np.array([x,y,z,*Q])
def sampled_xyz(points,spacing=.005):
 out=[]
 for a,b in zip(points,points[1:]):
  a=np.asarray(a,float);b=np.asarray(b,float);n=max(1,math.ceil(np.linalg.norm(b[:3]-a[:3])/spacing));out.extend(a+(b-a)*i/n for i in range(1,n+1))
 return np.asarray(out,np.float32)
def sampled_pix(points,spacing=.0045):
 out=[]
 for a,b in zip(points,points[1:]):
  pa=P(*a);pb=P(*b);n=max(1,math.ceil(np.linalg.norm(pb[:3]-pa[:3])/spacing));out.extend(pa+(pb-pa)*i/n for i in range(1,n+1))
 return np.asarray(out,np.float32)
def submit(a,note,video='none'):
 return r.submit('ee_pose',a,dt=.05,video=video,video_fps=5,cameras=('canvas_cam','side_cam','scene_cam'),note=note)
# Main stroke: leftward top bar, folded center and left hook. Contact is established vertically first.
o=r.get_obs(cameras=('canvas_cam',),video='none');cur=o.meta['proprio']['now'][7:10]
start=xy(379,400); high=np.r_[start,.12]
a=sampled_xyz([xyz(*cur),xyz(*high)],.006);z=submit(a,'stroke3 approach')
low=np.r_[start,.014];a=sampled_xyz([xyz(*high),xyz(*low)],.0045);z=submit(a,'stroke3 vertical contact',video='both');z.save('/app/output/run_stroke3_approach')
actual=z.proprio[-1,7:10];print('after descent',actual,'rows',len(a),'fails',sum(x.get('ik_failures',0) for x in z.meta['plan']))
if actual[2]>.019:
 z=submit(np.array([P(379,400,.014)]*3,np.float32),'stroke3 settle',video='both');actual=z.proprio[-1,7:10];print('after settle',actual)
line=[(379,400,.014),(400,400,.014),(425,410,.014),(450,411,.014),(470,410,.014),(473,421,.014),(470,443,.014),(466,465,.014),(455,490,.014),(437,509,.014),(413,526,.014),(389,536,.014),(369,541,.014),(348,552,.014),(330,564,.014),(313,570,.014),(296,568,.014),(282,560,.014),(274,550,.014),(270,540,.014)]
a=sampled_pix(line);z=submit(a,'stroke3 ink');z.save('/app/output/run_stroke3_line');print('line rows',len(a),'actual',z.proprio[-1,7:10],'fails',sum(x.get('ik_failures',0) for x in z.meta['plan']))
end=xy(270,540);highend=np.r_[end,.12];a=sampled_xyz([xyz(*np.r_[end,.014]),xyz(*highend)],.0045)
z=submit(a,'stroke3 lift');z.save('/app/output/run_stroke3_lift');print('lift',z.proprio[-1,7:10])
cur=z.proprio[-1,7:10];park=np.array([-.1,.15,.12]);a=sampled_xyz([xyz(*cur),xyz(*park)],.006);z=submit(a,'stroke3 park');o=r.get_obs(cameras=('canvas_cam',),video='none');from PIL import Image;Image.fromarray(o.last['canvas_cam']).save('/app/output/after_stroke3.png');print('parked',o.meta['proprio']['now'][7:10],'timeleft',o.meta['time_left_s'])
